          const coverSrc = getCoverPage(s.id);
          const imgHtml = coverSrc ? `<img class="cls1-cover-img" src="${coverSrc}" alt="${s.name} cover" loading="lazy">` : `<div class="scc-placeholder">${s.emoji}</div>`;
